INSERT OR REPLACE INTO words (id, text, phonetic, part_of_speech, meaning_en, meaning_zh, definition_en, definition_zh, examples, image, emoji, level, tags, created_at, updated_at) VALUES ('w-box', 'box', '/bɒks/', 'noun', 'a container you put things in', '盒子', 'You put things inside a box.', '你可以把东西放进盒子里。', '[{"en":"The box is on the desk.","zh":"盒子在书桌上。"},{"en":"Put the toys in the box.","zh":"把玩具放进盒子里。"}]', NULL, '📦', 1, '["core","object"]', 1793836800000, 1793836800000);
INSERT OR REPLACE INTO words (id, text, phonetic, part_of_speech, meaning_en, meaning_zh, definition_en, definition_zh, examples, image, emoji, level, tags, created_at, updated_at) VALUES ('w-bag', 'bag', '/bæɡ/', 'noun', 'a container for carrying things', '包；袋子', 'You put things inside a bag.', '你可以把东西放进包里。', '[{"en":"My bag is blue.","zh":"我的包是蓝色的。"},{"en":"I put the book in my bag.","zh":"我把书放进包里。"}]', NULL, '🎒', 1, '["core","object"]', 1793836800000, 1793836800000);
INSERT OR REPLACE INTO words (id, text, phonetic, part_of_speech, meaning_en, meaning_zh, definition_en, definition_zh, examples, image, emoji, level, tags, created_at, updated_at) VALUES ('w-paper', 'paper', '/ˈpeɪpə/', 'noun', 'thin material for writing or drawing', '纸', 'You can write or draw on paper.', '你可以在纸上写字或画画。', '[{"en":"I draw on paper.","zh":"我在纸上画画。"},{"en":"The paper is white.","zh":"纸是白色的。"}]', NULL, '📄', 1, '["core","material"]', 1793836800000, 1793836800000);
INSERT OR REPLACE INTO words (id, text, phonetic, part_of_speech, meaning_en, meaning_zh, definition_en, definition_zh, examples, image, emoji, level, tags, created_at, updated_at) VALUES ('w-pencil', 'pencil', '/ˈpensl/', 'noun', 'a tool for writing and drawing', '铅笔', 'You write or draw with a pencil.', '你用铅笔写字或画画。', '[{"en":"My pencil is sharp.","zh":"我的铅笔很尖。"},{"en":"Draw a line with your pencil.","zh":"用铅笔画出这条线。"}]', NULL, '✏️', 1, '["core","tool"]', 1793836800000, 1793836800000);
INSERT OR REPLACE INTO words (id, text, phonetic, part_of_speech, meaning_en, meaning_zh, definition_en, definition_zh, examples, image, emoji, level, tags, created_at, updated_at) VALUES ('w-ruler', 'ruler', '/ˈruːlə/', 'noun', 'a tool for drawing straight lines', '尺子', 'A ruler helps you draw a straight line.', '尺子可以帮你画直线。', '[{"en":"This ruler is long.","zh":"这把尺子很长。"},{"en":"Draw a line with the ruler.","zh":"用尺子画一条线。"}]', NULL, '📏', 1, '["core","tool"]', 1793836800000, 1793836800000);
INSERT OR REPLACE INTO words (id, text, phonetic, part_of_speech, meaning_en, meaning_zh, definition_en, definition_zh, examples, image, emoji, level, tags, created_at, updated_at) VALUES ('w-crayon', 'crayon', '/ˈkreɪɒn/', 'noun', 'a colored stick for drawing', '蜡笔', 'You draw with a crayon.', '你可以用蜡笔画画。', '[{"en":"My crayon is red.","zh":"我的蜡笔是红色的。"},{"en":"I draw a sun with a crayon.","zh":"我用蜡笔画了一个太阳。"}]', NULL, '🖍️', 1, '["core","tool"]', 1793836800000, 1793836800000);
INSERT OR REPLACE INTO words (id, text, phonetic, part_of_speech, meaning_en, meaning_zh, definition_en, definition_zh, examples, image, emoji, level, tags, created_at, updated_at) VALUES ('w-paint', 'paint', '/peɪnt/', 'noun / verb', 'color you put on paper, or to put it there', '颜料；涂色', 'Paint is color you put on paper or wood.', '颜料是涂在纸或木头上的颜色。', '[{"en":"The paint is blue.","zh":"颜料是蓝色的。"},{"en":"We paint a big box.","zh":"我们给一个大盒子涂色。"}]', NULL, '🎨', 1, '["core","tool"]', 1793836800000, 1793836800000);
INSERT OR REPLACE INTO words (id, text, phonetic, part_of_speech, meaning_en, meaning_zh, definition_en, definition_zh, examples, image, emoji, level, tags, created_at, updated_at) VALUES ('w-toy', 'toy', '/tɔɪ/', 'noun', 'a thing you play with', '玩具', 'A toy is something you play with.', '玩具是你玩的东西。', '[{"en":"This toy is a robot.","zh":"这个玩具是机器人。"},{"en":"I make a toy from a box.","zh":"我用盒子做了一个玩具。"}]', NULL, '🧸', 1, '["core","object"]', 1793836800000, 1793836800000);
INSERT OR REPLACE INTO words (id, text, phonetic, part_of_speech, meaning_en, meaning_zh, definition_en, definition_zh, examples, image, emoji, level, tags, created_at, updated_at) VALUES ('w-ball', 'ball', '/bɔːl/', 'noun', 'a round thing you play with', '球', 'You can throw and catch a ball.', '你可以扔球、接球。', '[{"en":"The ball is round.","zh":"球是圆的。"},{"en":"We play with a red ball.","zh":"我们玩一个红色的球。"}]', NULL, '⚽', 1, '["core","object"]', 1793836800000, 1793836800000);
INSERT OR REPLACE INTO words (id, text, phonetic, part_of_speech, meaning_en, meaning_zh, definition_en, definition_zh, examples, image, emoji, level, tags, created_at, updated_at) VALUES ('w-clock', 'clock', '/klɒk/', 'noun', 'a thing that shows the time', '时钟', 'A clock tells you what time it is.', '时钟会告诉你现在几点。', '[{"en":"The clock is on the wall.","zh":"时钟挂在墙上。"},{"en":"Look at the clock before we go.","zh":"出发前看一下时钟。"}]', NULL, '🕰️', 1, '["core","object"]', 1793836800000, 1793836800000);
INSERT OR REPLACE INTO words (id, text, phonetic, part_of_speech, meaning_en, meaning_zh, definition_en, definition_zh, examples, image, emoji, level, tags, created_at, updated_at) VALUES ('w-desk', 'desk', '/desk/', 'noun', 'a table for reading and writing', '书桌', 'You read and write at a desk.', '你在书桌旁读书写字。', '[{"en":"My desk is by the window.","zh":"我的书桌在窗边。"},{"en":"The pencil is on the desk.","zh":"铅笔在书桌上。"}]', NULL, '🗄️', 1, '["core","object"]', 1793836800000, 1793836800000);
INSERT OR REPLACE INTO words (id, text, phonetic, part_of_speech, meaning_en, meaning_zh, definition_en, definition_zh, examples, image, emoji, level, tags, created_at, updated_at) VALUES ('w-table', 'table', '/ˈteɪbl/', 'noun', 'a flat piece of furniture with legs', '桌子', 'You put things on a table.', '你把东西放在桌子上。', '[{"en":"The table is by the window.","zh":"桌子在窗边。"},{"en":"Put the paper on the table.","zh":"把纸放在桌子上。"}]', NULL, '🛋️', 1, '["core","object"]', 1793836800000, 1793836800000);
INSERT OR REPLACE INTO words (id, text, phonetic, part_of_speech, meaning_en, meaning_zh, definition_en, definition_zh, examples, image, emoji, level, tags, created_at, updated_at) VALUES ('w-chair', 'chair', '/tʃeə/', 'noun', 'a seat with a back', '椅子', 'You sit on a chair.', '你坐在椅子上。', '[{"en":"My chair is small.","zh":"我的椅子很小。"},{"en":"Sit on the chair, please.","zh":"请坐在椅子上。"}]', NULL, '🪑', 1, '["core","object"]', 1793836800000, 1793836800000);
