INSERT OR REPLACE INTO words (id, text, phonetic, part_of_speech, meaning_en, meaning_zh, definition_en, definition_zh, examples, image, emoji, level, tags, created_at, updated_at) VALUES ('w-make', 'make', '/meɪk/', 'verb', 'to create something', '制作', 'To make is to create something.', '制作就是做出一样东西。', '[{"en":"I make a card for my friend.","zh":"我给朋友做了一张卡片。"},{"en":"We make a boat from paper.","zh":"我们用纸做了一只船。"}]', NULL, '🛠️', 1, '["core","action"]', 1793836800000, 1793836800000);
INSERT OR REPLACE INTO words (id, text, phonetic, part_of_speech, meaning_en, meaning_zh, definition_en, definition_zh, examples, image, emoji, level, tags, created_at, updated_at) VALUES ('w-draw', 'draw', '/drɔː/', 'verb', 'to make a picture with a pencil or crayon', '画画', 'To draw is to make a picture.', '画画就是画出一幅图。', '[{"en":"I draw a cat.","zh":"我画了一只猫。"},{"en":"Draw a line on the paper.","zh":"在纸上画一条线。"}]', NULL, '🖊️', 1, '["core","action"]', 1793836800000, 1793836800000);
INSERT OR REPLACE INTO words (id, text, phonetic, part_of_speech, meaning_en, meaning_zh, definition_en, definition_zh, examples, image, emoji, level, tags, created_at, updated_at) VALUES ('w-choose', 'choose', '/tʃuːz/', 'verb', 'to pick the one you want', '选择', 'To choose is to pick the one you want.', '选择就是挑出你想要的那个。', '[{"en":"I choose the red crayon.","zh":"我选了红色的蜡笔。"},{"en":"Choose a box for your toys.","zh":"给你的玩具选一个盒子。"}]', NULL, '👉', 1, '["core","action"]', 1793836800000, 1793836800000);
INSERT OR REPLACE INTO words (id, text, phonetic, part_of_speech, meaning_en, meaning_zh, definition_en, definition_zh, examples, image, emoji, level, tags, created_at, updated_at) VALUES ('w-build', 'build', '/bɪld/', 'verb', 'to make something by joining parts', '建造', 'To build is to make something by putting parts together.', '建造就是把各个部分组合起来，做出一样东西。', '[{"en":"We build a treehouse.","zh":"我们建造了一座树屋。"},{"en":"They build houses with wood.","zh":"他们用木头建造房子。"}]', NULL, '🧱', 2, '["action","core"]', 1793836800000, 1793836800000);
INSERT OR REPLACE INTO words (id, text, phonetic, part_of_speech, meaning_en, meaning_zh, definition_en, definition_zh, examples, image, emoji, level, tags, created_at, updated_at) VALUES ('w-fix', 'fix', '/fɪks/', 'verb', 'to make something work again', '修理', 'To fix is to make something work again.', '修理就是把坏了的东西弄好。', '[{"en":"I fix my toy car.","zh":"我修好了我的玩具车。"},{"en":"Dad can fix the chair.","zh":"爸爸会修椅子。"}]', NULL, '🔧', 2, '["core","action"]', 1793836800000, 1793836800000);
INSERT OR REPLACE INTO words (id, text, phonetic, part_of_speech, meaning_en, meaning_zh, definition_en, definition_zh, examples, image, emoji, level, tags, created_at, updated_at) VALUES ('w-careful', 'careful', '/ˈkeəfl/', 'adjective', 'taking time so nothing goes wrong', '小心的；细心的', 'Being careful means taking your time so nothing goes wrong.', '小心就是慢慢来，不让事情出错。', '[{"en":"Be careful with the paint.","zh":"拿颜料时要小心。"},{"en":"She is careful when she paints.","zh":"她画画时很细心。"}]', NULL, '🧐', 2, '["core","abstract","emotional"]', 1793836800000, 1793836800000);
INSERT OR REPLACE INTO words (id, text, phonetic, part_of_speech, meaning_en, meaning_zh, definition_en, definition_zh, examples, image, emoji, level, tags, created_at, updated_at) VALUES ('w-sand', 'sand', '/sænd/', 'noun', 'tiny bits of rock', '沙子', 'Sand is made of tiny bits of rock.', '沙子是由很小的石头颗粒组成的。', '[{"en":"The sand is soft.","zh":"沙子很软。"},{"en":"We put sand in the box.","zh":"我们把沙子放进盒子里。"}]', NULL, '🏖️', 1, '["core","material"]', 1793836800000, 1793836800000);
INSERT OR REPLACE INTO words (id, text, phonetic, part_of_speech, meaning_en, meaning_zh, definition_en, definition_zh, examples, image, emoji, level, tags, created_at, updated_at) VALUES ('w-glass', 'glass', '/ɡlɑːs/', 'noun', 'a hard, clear material', '玻璃', 'Glass is a hard, clear material.', '玻璃是一种又硬又透明的材料。', '[{"en":"The window is made of glass.","zh":"窗户是玻璃做的。"},{"en":"Glass is clear and hard.","zh":"玻璃透明又坚硬。"}]', NULL, '🪟', 2, '["core","material"]', 1793836800000, 1793836800000);
