INSERT OR REPLACE INTO words (id, text, phonetic, part_of_speech, meaning_en, meaning_zh, definition_en, definition_zh, examples, image, emoji, level, tags, created_at, updated_at) VALUES ('w-wool', 'wool', '/wʊl/', 'noun', 'soft hair from a sheep', '羊毛', 'Wool is soft hair from a sheep.', '羊毛是绵羊身上柔软的毛。', '[{"en":"My hat is made of wool.","zh":"我的帽子是羊毛做的。"},{"en":"Wool comes from sheep.","zh":"羊毛来自绵羊。"}]', NULL, '🧶', 3, '["thematic","material"]', 1793836800000, 1793836800000);
INSERT OR REPLACE INTO words (id, text, phonetic, part_of_speech, meaning_en, meaning_zh, definition_en, definition_zh, examples, image, emoji, level, tags, created_at, updated_at) VALUES ('w-gold', 'gold', '/ɡəʊld/', 'noun', 'a yellow metal', '金子', 'Gold is a yellow metal.', '金子是一种黄色的金属。', '[{"en":"The ring is made of gold.","zh":"戒指是金子做的。"},{"en":"Gold is a yellow metal.","zh":"金子是一种黄色的金属。"}]', NULL, '🪙', 3, '["thematic","material"]', 1793836800000, 1793836800000);
INSERT OR REPLACE INTO words (id, text, phonetic, part_of_speech, meaning_en, meaning_zh, definition_en, definition_zh, examples, image, emoji, level, tags, created_at, updated_at) VALUES ('w-silver', 'silver', '/ˈsɪlvə/', 'noun', 'a shiny gray metal', '银', 'Silver is a shiny gray metal.', '银子是一种闪亮的灰色金属。', '[{"en":"The spoon is made of silver.","zh":"勺子是用银做的。"},{"en":"Silver is shiny and gray.","zh":"银子闪亮，是灰色的。"}]', NULL, '🥈', 3, '["thematic","material"]', 1793836800000, 1793836800000);
INSERT OR REPLACE INTO words (id, text, phonetic, part_of_speech, meaning_en, meaning_zh, definition_en, definition_zh, examples, image, emoji, level, tags, created_at, updated_at) VALUES ('w-stone', 'stone', '/stəʊn/', 'noun', 'hard rock', '石头', 'Stone is hard rock.', '石头是坚硬的岩石。', '[{"en":"The wall is made of stone.","zh":"墙是用石头砌的。"},{"en":"The stone is heavy.","zh":"这块石头很重。"}]', NULL, '🪨', 3, '["thematic","material"]', 1793836800000, 1793836800000);
INSERT OR REPLACE INTO words (id, text, phonetic, part_of_speech, meaning_en, meaning_zh, definition_en, definition_zh, examples, image, emoji, level, tags, created_at, updated_at) VALUES ('w-scissors', 'scissors', '/ˈsɪzəz/', 'noun', 'a tool with two blades for cutting', '剪刀', 'Scissors are a tool with two blades for cutting.', '剪刀是有两片刀刃、用来剪东西的工具。', '[{"en":"I cut the paper with scissors.","zh":"我用剪刀剪纸。"},{"en":"These scissors are sharp.","zh":"这把剪刀很锋利。"}]', NULL, '✂️', 3, '["thematic","tool"]', 1793836800000, 1793836800000);
INSERT OR REPLACE INTO words (id, text, phonetic, part_of_speech, meaning_en, meaning_zh, definition_en, definition_zh, examples, image, emoji, level, tags, created_at, updated_at) VALUES ('w-glue', 'glue', '/ɡluː/', 'noun / verb', 'a sticky liquid that joins things', '胶水；粘', 'Glue is a sticky liquid that joins things.', '胶水是一种黏黏的液体，可以把东西粘在一起。', '[{"en":"I use glue to fix the paper.","zh":"我用胶水把纸粘好。"},{"en":"The glue is sticky.","zh":"胶水黏黏的。"}]', NULL, '🧪', 3, '["thematic","tool"]', 1793836800000, 1793836800000);
INSERT OR REPLACE INTO words (id, text, phonetic, part_of_speech, meaning_en, meaning_zh, definition_en, definition_zh, examples, image, emoji, level, tags, created_at, updated_at) VALUES ('w-brush', 'brush', '/brʌʃ/', 'noun', 'a tool for painting or cleaning', '刷子', 'You use a brush to paint or clean.', '你可以用刷子画画或清扫。', '[{"en":"This brush is for paint.","zh":"这把刷子是用来画画的。"},{"en":"Clean the brush after you paint.","zh":"画完后要清洗刷子。"}]', NULL, '🖌️', 3, '["thematic","tool"]', 1793836800000, 1793836800000);
INSERT OR REPLACE INTO words (id, text, phonetic, part_of_speech, meaning_en, meaning_zh, definition_en, definition_zh, examples, image, emoji, level, tags, created_at, updated_at) VALUES ('w-repair', 'repair', '/rɪˈpeə/', 'verb', 'to fix something broken', '修理', 'To repair is to fix something broken.', '修理就是把坏了的东西修好。', '[{"en":"We repair the broken chair.","zh":"我们修理坏了的椅子。"},{"en":"He can repair the toy.","zh":"他会修理这个玩具。"}]', NULL, '🛠️', 3, '["core","action"]', 1793836800000, 1793836800000);
INSERT OR REPLACE INTO words (id, text, phonetic, part_of_speech, meaning_en, meaning_zh, definition_en, definition_zh, examples, image, emoji, level, tags, created_at, updated_at) VALUES ('w-safe', 'safe', '/seɪf/', 'adjective', 'not dangerous', '安全的', 'Safe means not dangerous.', '安全就是没有危险。', '[{"en":"The workshop is safe.","zh":"工作间很安全。"},{"en":"Wear gloves to stay safe.","zh":"戴上手套保持安全。"}]', NULL, '🛡️', 2, '["core","abstract"]', 1793836800000, 1793836800000);
INSERT OR REPLACE INTO words (id, text, phonetic, part_of_speech, meaning_en, meaning_zh, definition_en, definition_zh, examples, image, emoji, level, tags, created_at, updated_at) VALUES ('w-strong', 'strong', '/strɒŋ/', 'adjective', 'hard to break', '结实的；强壮的', 'Strong means hard to break.', '结实就是不容易坏。', '[{"en":"The box is strong.","zh":"这个盒子很结实。"},{"en":"A strong bridge can hold a car.","zh":"结实的桥能承受汽车。"}]', NULL, '💪', 2, '["core","abstract"]', 1793836800000, 1793836800000);
INSERT OR REPLACE INTO words (id, text, phonetic, part_of_speech, meaning_en, meaning_zh, definition_en, definition_zh, examples, image, emoji, level, tags, created_at, updated_at) VALUES ('w-easy', 'easy', '/ˈiːzi/', 'adjective', 'not difficult', '容易的', 'Easy means not difficult.', '容易就是不难。', '[{"en":"This puzzle is easy.","zh":"这个拼图很容易。"},{"en":"The first step is easy.","zh":"第一步很容易。"}]', NULL, '✅', 2, '["core","abstract"]', 1793836800000, 1793836800000);
INSERT OR REPLACE INTO words (id, text, phonetic, part_of_speech, meaning_en, meaning_zh, definition_en, definition_zh, examples, image, emoji, level, tags, created_at, updated_at) VALUES ('w-difficult', 'difficult', '/ˈdɪfɪkəlt/', 'adjective', 'not easy', '困难的', 'Difficult means not easy.', '困难就是不容易。', '[{"en":"The big puzzle is difficult.","zh":"这个大拼图很难。"},{"en":"It is difficult to build a tower.","zh":"搭一座高塔很难。"}]', NULL, '❓', 2, '["core","abstract"]', 1793836800000, 1793836800000);
INSERT OR REPLACE INTO words (id, text, phonetic, part_of_speech, meaning_en, meaning_zh, definition_en, definition_zh, examples, image, emoji, level, tags, created_at, updated_at) VALUES ('w-cut', 'cut', '/kʌt/', 'verb', 'to divide something with scissors or a knife', '剪；切', 'To cut is to divide something with scissors or a knife.', '剪就是用剪刀或刀把东西分开。', '[{"en":"I cut the paper.","zh":"我剪纸。"},{"en":"Cut the paper in half.","zh":"把纸剪成两半。"}]', NULL, '✂️', 3, '["core","action"]', 1793836800000, 1793836800000);
INSERT OR REPLACE INTO words (id, text, phonetic, part_of_speech, meaning_en, meaning_zh, definition_en, definition_zh, examples, image, emoji, level, tags, created_at, updated_at) VALUES ('w-design', 'design', '/dɪˈzaɪn/', 'verb', 'to plan how something will look', '设计', 'To design is to plan how something will look.', '设计就是计划一样东西要长什么样。', '[{"en":"We design a new toy.","zh":"我们设计一个新玩具。"},{"en":"She designs a poster.","zh":"她设计了一张海报。"}]', NULL, '📐', 3, '["thematic","action"]', 1793836800000, 1793836800000);
INSERT OR REPLACE INTO words (id, text, phonetic, part_of_speech, meaning_en, meaning_zh, definition_en, definition_zh, examples, image, emoji, level, tags, created_at, updated_at) VALUES ('w-invent', 'invent', '/ɪnˈvent/', 'verb', 'to make something new', '发明', 'To invent is to make something new.', '发明就是做出新东西。', '[{"en":"They invent a funny machine.","zh":"他们发明了一台有趣的机器。"},{"en":"I invent a game with boxes.","zh":"我用盒子发明了一个游戏。"}]', NULL, '💡', 3, '["thematic","action"]', 1793836800000, 1793836800000);
INSERT OR REPLACE INTO words (id, text, phonetic, part_of_speech, meaning_en, meaning_zh, definition_en, definition_zh, examples, image, emoji, level, tags, created_at, updated_at) VALUES ('w-collect', 'collect', '/kəˈlekt/', 'verb', 'to bring things together', '收集', 'To collect is to bring things together.', '收集就是把东西聚在一起。', '[{"en":"We collect boxes for the project.","zh":"我们为这个项目收集盒子。"},{"en":"She collects small stones.","zh":"她收集小石头。"}]', NULL, '🧺', 3, '["core","action"]', 1793836800000, 1793836800000);
INSERT OR REPLACE INTO words (id, text, phonetic, part_of_speech, meaning_en, meaning_zh, definition_en, definition_zh, examples, image, emoji, level, tags, created_at, updated_at) VALUES ('w-prepare', 'prepare', '/prɪˈpeə/', 'verb', 'to get things ready', '准备', 'To prepare is to get things ready.', '准备就是把东西准备好。', '[{"en":"We prepare the paper and paint.","zh":"我们准备好纸和颜料。"},{"en":"Prepare your desk before you start.","zh":"开始前把书桌准备好。"}]', NULL, '📋', 3, '["core","action"]', 1793836800000, 1793836800000);
INSERT OR REPLACE INTO words (id, text, phonetic, part_of_speech, meaning_en, meaning_zh, definition_en, definition_zh, examples, image, emoji, level, tags, created_at, updated_at) VALUES ('w-decide', 'decide', '/dɪˈsaɪd/', 'verb', 'to choose what to do', '决定', 'To decide is to choose what to do.', '决定就是选择要做什么。', '[{"en":"We decide to build a boat.","zh":"我们决定造一只船。"},{"en":"You can decide which color to use.","zh":"你可以决定用哪种颜色。"}]', NULL, '🤔', 3, '["core","action"]', 1793836800000, 1793836800000);
INSERT OR REPLACE INTO words (id, text, phonetic, part_of_speech, meaning_en, meaning_zh, definition_en, definition_zh, examples, image, emoji, level, tags, created_at, updated_at) VALUES ('w-believe', 'believe', '/bɪˈliːv/', 'verb', 'to think something is true', '相信', 'To believe is to think something is true.', '相信就是认为某件事是真的。', '[{"en":"I believe we can finish it.","zh":"我相信我们能完成它。"},{"en":"She believes the box is strong.","zh":"她相信这个盒子很结实。"}]', NULL, '💭', 3, '["core","abstract"]', 1793836800000, 1793836800000);
INSERT OR REPLACE INTO words (id, text, phonetic, part_of_speech, meaning_en, meaning_zh, definition_en, definition_zh, examples, image, emoji, level, tags, created_at, updated_at) VALUES ('w-explain', 'explain', '/ɪkˈspleɪn/', 'verb', 'to make something clear', '解释', 'To explain is to make something clear.', '解释就是把事情说清楚。', '[{"en":"Please explain your idea.","zh":"请解释你的想法。"},{"en":"He explains how the machine works.","zh":"他解释这台机器怎么运作。"}]', NULL, '💬', 3, '["core","action"]', 1793836800000, 1793836800000);
INSERT OR REPLACE INTO words (id, text, phonetic, part_of_speech, meaning_en, meaning_zh, definition_en, definition_zh, examples, image, emoji, level, tags, created_at, updated_at) VALUES ('w-improve', 'improve', '/ɪmˈpruːv/', 'verb', 'to make something better', '改进', 'To improve is to make something better.', '改进就是把东西变得更好。', '[{"en":"We improve our treehouse.","zh":"我们改进我们的树屋。"},{"en":"Paint can improve an old box.","zh":"颜料可以让旧盒子变好看。"}]', NULL, '📈', 3, '["core","action"]', 1793836800000, 1793836800000);
INSERT OR REPLACE INTO words (id, text, phonetic, part_of_speech, meaning_en, meaning_zh, definition_en, definition_zh, examples, image, emoji, level, tags, created_at, updated_at) VALUES ('w-together', 'together', '/təˈɡeðə/', 'adverb', 'with another person or in a group', '一起', 'Together means with another person or in a group.', '一起就是和别人或一群人共同做一件事。', '[{"en":"We build the treehouse together.","zh":"我们一起建造树屋。"},{"en":"The friends play together.","zh":"朋友们一起玩。"}]', NULL, '🤝', 3, '["core","abstract","emotional"]', 1793836800000, 1793836800000);
INSERT OR REPLACE INTO words (id, text, phonetic, part_of_speech, meaning_en, meaning_zh, definition_en, definition_zh, examples, image, emoji, level, tags, created_at, updated_at) VALUES ('w-happy', 'happy', '/ˈhæpi/', 'adjective', 'feeling good', '开心的', 'Happy means feeling good.', '开心就是感觉很好。', '[{"en":"I am happy with my picture.","zh":"我对我的画很满意。"},{"en":"The children are happy to build together.","zh":"孩子们一起搭建很开心。"}]', NULL, '😊', 1, '["core","emotional"]', 1793836800000, 1793836800000);
INSERT OR REPLACE INTO words (id, text, phonetic, part_of_speech, meaning_en, meaning_zh, definition_en, definition_zh, examples, image, emoji, level, tags, created_at, updated_at) VALUES ('w-excited', 'excited', '/ɪkˈsaɪtɪd/', 'adjective', 'feeling full of energy about something', '兴奋的', 'Excited means feeling full of energy about something.', '兴奋就是为某件事特别高兴、特别有精神。', '[{"en":"We are excited about the project.","zh":"我们对这个项目很兴奋。"},{"en":"She is excited to start.","zh":"她兴奋地准备开始。"}]', NULL, '🤩', 3, '["core","emotional"]', 1793836800000, 1793836800000);
INSERT OR REPLACE INTO words (id, text, phonetic, part_of_speech, meaning_en, meaning_zh, definition_en, definition_zh, examples, image, emoji, level, tags, created_at, updated_at) VALUES ('w-worried', 'worried', '/ˈwʌrid/', 'adjective', 'feeling that something bad may happen', '担心的', 'Worried means feeling that something bad may happen.', '担心就是觉得可能会有不好的事发生。', '[{"en":"She is worried about the mess.","zh":"她担心弄得一团糟。"},{"en":"Do not be worried; we can fix it.","zh":"别担心，我们能修好。"}]', NULL, '😟', 3, '["core","emotional"]', 1793836800000, 1793836800000);
INSERT OR REPLACE INTO words (id, text, phonetic, part_of_speech, meaning_en, meaning_zh, definition_en, definition_zh, examples, image, emoji, level, tags, created_at, updated_at) VALUES ('w-brave', 'brave', '/breɪv/', 'adjective', 'not afraid to try', '勇敢的', 'Brave means not afraid to try.', '勇敢就是不怕尝试。', '[{"en":"He is brave and tries again.","zh":"他很勇敢，又试了一次。"},{"en":"Be brave and show your design.","zh":"勇敢一点，展示你的设计。"}]', NULL, '🦸', 2, '["core","emotional"]', 1793836800000, 1793836800000);
INSERT OR REPLACE INTO words (id, text, phonetic, part_of_speech, meaning_en, meaning_zh, definition_en, definition_zh, examples, image, emoji, level, tags, created_at, updated_at) VALUES ('w-clever', 'clever', '/ˈklevə/', 'adjective', 'good at thinking and making things', '聪明的', 'Clever means good at thinking and making things.', '聪明就是很会思考和做东西。', '[{"en":"She is clever with boxes.","zh":"她很会用盒子做东西。"},{"en":"That is a clever idea.","zh":"那是个聪明的主意。"}]', NULL, '🧠', 2, '["core","emotional"]', 1793836800000, 1793836800000);
INSERT OR REPLACE INTO words (id, text, phonetic, part_of_speech, meaning_en, meaning_zh, definition_en, definition_zh, examples, image, emoji, level, tags, created_at, updated_at) VALUES ('w-kind', 'kind', '/kaɪnd/', 'adjective', 'nice and helpful to others', '友善的', 'Kind means nice and helpful to others.', '友善就是对别人很好、乐于帮忙。', '[{"en":"It is kind to help.","zh":"帮助别人是友善的。"},{"en":"Our teacher is kind.","zh":"我们的老师很友善。"}]', NULL, '💛', 3, '["core","emotional"]', 1793836800000, 1793836800000);
INSERT OR REPLACE INTO words (id, text, phonetic, part_of_speech, meaning_en, meaning_zh, definition_en, definition_zh, examples, image, emoji, level, tags, created_at, updated_at) VALUES ('w-friendly', 'friendly', '/ˈfrendli/', 'adjective', 'nice and easy to talk to', '友好的', 'Friendly means nice and easy to talk to.', '友好就是对人亲切、容易相处。', '[{"en":"The teacher is friendly.","zh":"老师很友好。"},{"en":"The new child is friendly.","zh":"新来的孩子很友好。"}]', NULL, '🤗', 3, '["core","emotional"]', 1793836800000, 1793836800000);
INSERT OR REPLACE INTO words (id, text, phonetic, part_of_speech, meaning_en, meaning_zh, definition_en, definition_zh, examples, image, emoji, level, tags, created_at, updated_at) VALUES ('w-beautiful', 'beautiful', '/ˈbjuːtɪfl/', 'adjective', 'very nice to look at', '美丽的', 'Beautiful means very nice to look at.', '美丽就是看起来很好看。', '[{"en":"My picture is beautiful.","zh":"我的画很美丽。"},{"en":"We make a beautiful card.","zh":"我们做了一张美丽的卡片。"}]', NULL, '🌟', 1, '["core","abstract"]', 1793836800000, 1793836800000);
INSERT OR REPLACE INTO words (id, text, phonetic, part_of_speech, meaning_en, meaning_zh, definition_en, definition_zh, examples, image, emoji, level, tags, created_at, updated_at) VALUES ('w-important', 'important', '/ɪmˈpɔːtnt/', 'adjective', 'matters a lot', '重要的', 'Important means that it matters a lot.', '重要就是很要紧。', '[{"en":"It is important to be careful.","zh":"小心很重要。"},{"en":"Sleep is important for children.","zh":"睡眠对孩子很重要。"}]', NULL, '❗', 3, '["core","abstract"]', 1793836800000, 1793836800000);
INSERT OR REPLACE INTO words (id, text, phonetic, part_of_speech, meaning_en, meaning_zh, definition_en, definition_zh, examples, image, emoji, level, tags, created_at, updated_at) VALUES ('w-ready', 'ready', '/ˈredi/', 'adjective', 'prepared to start', '准备好的', 'Ready means prepared to start.', '准备好就是可以开始了。', '[{"en":"We are ready to start.","zh":"我们准备好开始了。"},{"en":"The paint is ready to use.","zh":"颜料准备好可以用了。"}]', NULL, '🏁', 3, '["core","abstract"]', 1793836800000, 1793836800000);
INSERT OR REPLACE INTO words (id, text, phonetic, part_of_speech, meaning_en, meaning_zh, definition_en, definition_zh, examples, image, emoji, level, tags, created_at, updated_at) VALUES ('w-explore-1-01', 'beach', '/biːtʃ/', 'noun', 'the sand next to the sea', '海滩；沙滩', 'You can walk on the sand next to the water.', '你可以在水边的沙子上散步。', '[{"en":"We play on the beach.","zh":"我们在海滩上玩。"},{"en":"The beach is warm today.","zh":"今天沙滩上很暖和。"}]', NULL, '🏖️', 1, '["core","place"]', 1793836800000, 1793836800000);
INSERT OR REPLACE INTO words (id, text, phonetic, part_of_speech, meaning_en, meaning_zh, definition_en, definition_zh, examples, image, emoji, level, tags, created_at, updated_at) VALUES ('w-explore-1-02', 'sea', '/siː/', 'noun', 'the big water with salt in it', '大海', 'Fish live in the sea, and it is very big.', '鱼生活在大海里，大海非常大。', '[{"en":"The sea is blue.","zh":"大海是蓝色的。"},{"en":"We can see the sea from here.","zh":"我们从这里能看到大海。"}]', NULL, '🌊', 1, '["core","nature"]', 1793836800000, 1793836800000);
INSERT OR REPLACE INTO words (id, text, phonetic, part_of_speech, meaning_en, meaning_zh, definition_en, definition_zh, examples, image, emoji, level, tags, created_at, updated_at) VALUES ('w-explore-1-03', 'tree', '/triː/', 'noun', 'a tall plant with a trunk and leaves', '树', 'A tree has a trunk and many leaves.', '树有树干和许多叶子。', '[{"en":"The tree is very tall.","zh":"这棵树很高。"},{"en":"A bird is in the tree.","zh":"一只鸟在树上。"}]', NULL, '🌳', 1, '["core","nature"]', 1793836800000, 1793836800000);
INSERT OR REPLACE INTO words (id, text, phonetic, part_of_speech, meaning_en, meaning_zh, definition_en, definition_zh, examples, image, emoji, level, tags, created_at, updated_at) VALUES ('w-explore-1-04', 'flower', '/ˈflaʊə/', 'noun', 'a pretty plant part that smells nice', '花', 'A flower is pretty and can smell nice.', '花很漂亮，还可能有香味。', '[{"en":"This flower is pink.","zh":"这朵花是粉色的。"},{"en":"I put a flower in a glass.","zh":"我把一朵花放进杯子里。"}]', NULL, '🌸', 1, '["core","nature"]', 1793836800000, 1793836800000);
INSERT OR REPLACE INTO words (id, text, phonetic, part_of_speech, meaning_en, meaning_zh, definition_en, definition_zh, examples, image, emoji, level, tags, created_at, updated_at) VALUES ('w-explore-1-05', 'garden', '/ˈɡɑːdn/', 'noun', 'a place where plants grow', '花园', 'You grow flowers and plants in a garden.', '你在花园里种花和植物。', '[{"en":"Our garden has many flowers.","zh":"我们的花园里有很多花。"},{"en":"Dad works in the garden.","zh":"爸爸在花园里干活。"}]', NULL, '🌷', 1, '["core","place"]', 1793836800000, 1793836800000);
INSERT OR REPLACE INTO words (id, text, phonetic, part_of_speech, meaning_en, meaning_zh, definition_en, definition_zh, examples, image, emoji, level, tags, created_at, updated_at) VALUES ('w-explore-1-06', 'animal', '/ˈænɪml/', 'noun', 'a living thing that is not a plant', '动物', 'An animal can move and eat. A dog is an animal.', '动物会动也会吃东西。狗就是一种动物。', '[{"en":"An animal lives in the forest.","zh":"一只动物住在森林里。"},{"en":"The cat is a small animal.","zh":"猫是一种小动物。"}]', NULL, '🐾', 1, '["core","animal"]', 1793836800000, 1793836800000);
INSERT OR REPLACE INTO words (id, text, phonetic, part_of_speech, meaning_en, meaning_zh, definition_en, definition_zh, examples, image, emoji, level, tags, created_at, updated_at) VALUES ('w-explore-1-07', 'bird', '/bɜːd/', 'noun', 'an animal with wings and feathers', '鸟', 'A bird has wings and can fly.', '鸟有翅膀，会飞。', '[{"en":"A bird is singing.","zh":"一只鸟在唱歌。"},{"en":"That bird has blue wings.","zh":"那只鸟有蓝色的翅膀。"}]', NULL, '🐦', 1, '["core","animal"]', 1793836800000, 1793836800000);
INSERT OR REPLACE INTO words (id, text, phonetic, part_of_speech, meaning_en, meaning_zh, definition_en, definition_zh, examples, image, emoji, level, tags, created_at, updated_at) VALUES ('w-explore-1-08', 'shell', '/ʃel/', 'noun', 'a hard cover that some animals live in', '贝壳', 'You can find a shell on the beach.', '你可以在海滩上找到贝壳。', '[{"en":"I found a shell on the sand.","zh":"我在沙滩上找到一个贝壳。"},{"en":"This shell is pink.","zh":"这个贝壳是粉色的。"}]', NULL, '🐚', 1, '["core","object"]', 1793836800000, 1793836800000);
INSERT OR REPLACE INTO words (id, text, phonetic, part_of_speech, meaning_en, meaning_zh, definition_en, definition_zh, examples, image, emoji, level, tags, created_at, updated_at) VALUES ('w-explore-1-09', 'sun', '/sʌn/', 'noun', 'the bright light in the sky during the day', '太阳', 'The sun gives us light and makes the day warm.', '太阳给我们光，让白天变得温暖。', '[{"en":"The sun is bright today.","zh":"今天太阳很亮。"},{"en":"The sun is in the sky.","zh":"太阳在天空中。"}]', NULL, '☀️', 1, '["core","nature"]', 1793836800000, 1793836800000);
INSERT OR REPLACE INTO words (id, text, phonetic, part_of_speech, meaning_en, meaning_zh, definition_en, definition_zh, examples, image, emoji, level, tags, created_at, updated_at) VALUES ('w-explore-1-10', 'boat', '/bəʊt/', 'noun', 'a small thing that floats and carries people on water', '小船', 'You can ride in a boat on the water.', '你可以坐小船在水上走。', '[{"en":"The boat is on the lake.","zh":"小船在湖上。"},{"en":"We go in a boat.","zh":"我们坐小船。"}]', NULL, '⛵', 1, '["core","object"]', 1793836800000, 1793836800000);
INSERT OR REPLACE INTO words (id, text, phonetic, part_of_speech, meaning_en, meaning_zh, definition_en, definition_zh, examples, image, emoji, level, tags, created_at, updated_at) VALUES ('w-explore-1-11', 'river', '/ˈrɪvə/', 'noun', 'a long line of water that moves to the sea', '河流', 'Water moves along a river to the sea.', '水沿着河流向大海流去。', '[{"en":"The river is long and blue.","zh":"这条河又长又蓝。"},{"en":"Fish swim in the river.","zh":"鱼在河里游。"}]', NULL, '🏞️', 2, '["core","nature"]', 1793836800000, 1793836800000);
INSERT OR REPLACE INTO words (id, text, phonetic, part_of_speech, meaning_en, meaning_zh, definition_en, definition_zh, examples, image, emoji, level, tags, created_at, updated_at) VALUES ('w-explore-1-12', 'forest', '/ˈfɒrɪst/', 'noun', 'a big place with many trees', '森林', 'Many trees grow together in a forest.', '许多树长在一起，就是森林。', '[{"en":"We walk in the forest.","zh":"我们在森林里散步。"},{"en":"The forest is quiet.","zh":"森林里很安静。"}]', NULL, '🌲', 2, '["core","place"]', 1793836800000, 1793836800000);
INSERT OR REPLACE INTO words (id, text, phonetic, part_of_speech, meaning_en, meaning_zh, definition_en, definition_zh, examples, image, emoji, level, tags, created_at, updated_at) VALUES ('w-explore-1-13', 'mountain', '/ˈmaʊntən/', 'noun', 'a very high hill', '山；高山', 'A mountain is very high and made of rock.', '山很高，由岩石组成。', '[{"en":"The mountain is high.","zh":"这座山很高。"},{"en":"We climb the mountain.","zh":"我们爬山。"}]', NULL, '⛰️', 2, '["core","nature"]', 1793836800000, 1793836800000);
INSERT OR REPLACE INTO words (id, text, phonetic, part_of_speech, meaning_en, meaning_zh, definition_en, definition_zh, examples, image, emoji, level, tags, created_at, updated_at) VALUES ('w-explore-1-14', 'island', '/ˈaɪlənd/', 'noun', 'land with water all around it', '岛', 'An island has water all around it.', '岛的四周都是水。', '[{"en":"The island is small.","zh":"这个岛很小。"},{"en":"We take a boat to the island.","zh":"我们坐船去岛上。"}]', NULL, '🏝️', 2, '["core","place"]', 1793836800000, 1793836800000);
INSERT OR REPLACE INTO words (id, text, phonetic, part_of_speech, meaning_en, meaning_zh, definition_en, definition_zh, examples, image, emoji, level, tags, created_at, updated_at) VALUES ('w-explore-1-15', 'lake', '/leɪk/', 'noun', 'a big pool of water with land around it', '湖', 'A lake is water with land all around it.', '湖是四周被陆地围住的水。', '[{"en":"The lake is calm today.","zh":"今天湖面很平静。"},{"en":"We swim in the lake.","zh":"我们在湖里游泳。"}]', NULL, '💧', 2, '["core","nature"]', 1793836800000, 1793836800000);
INSERT OR REPLACE INTO words (id, text, phonetic, part_of_speech, meaning_en, meaning_zh, definition_en, definition_zh, examples, image, emoji, level, tags, created_at, updated_at) VALUES ('w-explore-1-16', 'rock', '/rɒk/', 'noun', 'a hard piece of stone', '岩石；石头', 'A rock is hard and comes from the ground.', '岩石很硬，来自地下。', '[{"en":"I sit on a big rock.","zh":"我坐在一块大石头上。"},{"en":"The rock is heavy.","zh":"这块石头很重。"}]', NULL, '🪨', 2, '["core","material"]', 1793836800000, 1793836800000);
INSERT OR REPLACE INTO words (id, text, phonetic, part_of_speech, meaning_en, meaning_zh, definition_en, definition_zh, examples, image, emoji, level, tags, created_at, updated_at) VALUES ('w-explore-1-17', 'grass', '/ɡrɑːs/', 'noun', 'short green plants that cover the ground', '草', 'Grass is green and grows on the ground.', '草是绿色的，长在地上。', '[{"en":"The grass is green.","zh":"草是绿色的。"},{"en":"We sit on the grass.","zh":"我们坐在草地上。"}]', NULL, '🌿', 2, '["core","nature"]', 1793836800000, 1793836800000);
INSERT OR REPLACE INTO words (id, text, phonetic, part_of_speech, meaning_en, meaning_zh, definition_en, definition_zh, examples, image, emoji, level, tags, created_at, updated_at) VALUES ('w-explore-1-18', 'storm', '/stɔːm/', 'noun', 'strong wind and rain', '暴风雨', 'A storm has strong wind and a lot of rain.', '暴风雨有很大的风和很多雨。', '[{"en":"The storm is loud.","zh":"暴风雨很响。"},{"en":"We stay inside during the storm.","zh":"暴风雨时我们待在屋里。"}]', NULL, '⛈️', 3, '["thematic","weather"]', 1793836800000, 1793836800000);
INSERT OR REPLACE INTO words (id, text, phonetic, part_of_speech, meaning_en, meaning_zh, definition_en, definition_zh, examples, image, emoji, level, tags, created_at, updated_at) VALUES ('w-explore-1-19', 'cave', '/keɪv/', 'noun', 'a big hole in a hill or rock', '山洞；洞穴', 'A cave is a dark hole in a hill or under the ground.', '山洞是山里的黑洞，或者地下的洞。', '[{"en":"The cave is dark.","zh":"山洞里很黑。"},{"en":"We look inside the cave.","zh":"我们往山洞里看。"}]', NULL, '🕳️', 3, '["thematic","place"]', 1793836800000, 1793836800000);
INSERT OR REPLACE INTO words (id, text, phonetic, part_of_speech, meaning_en, meaning_zh, definition_en, definition_zh, examples, image, emoji, level, tags, created_at, updated_at) VALUES ('w-explore-1-20', 'wonderful', '/ˈwʌndəfl/', 'adjective', 'very good and making you feel happy', '美妙的；很棒的', 'Something wonderful is very good and makes you smile.', '美妙的事物非常好，会让你笑起来。', '[{"en":"The view is wonderful.","zh":"这里的景色美极了。"},{"en":"We had a wonderful day.","zh":"我们度过了美好的一天。"}]', NULL, '✨', 3, '["core","abstract","emotional"]', 1793836800000, 1793836800000);
INSERT OR REPLACE INTO words (id, text, phonetic, part_of_speech, meaning_en, meaning_zh, definition_en, definition_zh, examples, image, emoji, level, tags, created_at, updated_at) VALUES ('w-explore-2-01', 'map', '/mæp/', 'noun', 'a picture that shows where places are', '地图', 'A map shows you where places are.', '地图告诉你各个地方在哪里。', '[{"en":"Look at the map.","zh":"看看地图。"},{"en":"The map shows the river.","zh":"地图上画着这条河。"}]', NULL, '🗺️', 2, '["thematic","object"]', 1793836800000, 1793836800000);
INSERT OR REPLACE INTO words (id, text, phonetic, part_of_speech, meaning_en, meaning_zh, definition_en, definition_zh, examples, image, emoji, level, tags, created_at, updated_at) VALUES ('w-explore-2-02', 'between', '/bɪˈtwiːn/', 'preposition', 'in the space in the middle of two things', '在……之间', 'When something is between two things, it is in the middle.', '一个东西在两个东西中间，就是在它们之间。', '[{"en":"The gate is between two trees.","zh":"大门在两棵树之间。"},{"en":"I sit between Mum and Dad.","zh":"我坐在妈妈和爸爸中间。"}]', NULL, '↔️', 1, '["core","direction"]', 1793836800000, 1793836800000);
INSERT OR REPLACE INTO words (id, text, phonetic, part_of_speech, meaning_en, meaning_zh, definition_en, definition_zh, examples, image, emoji, level, tags, created_at, updated_at) VALUES ('w-explore-2-03', 'road', '/rəʊd/', 'noun', 'a hard way for cars to travel', '路；马路', 'Cars and buses drive on a road.', '汽车和公共汽车在马路上行驶。', '[{"en":"The road goes to the village.","zh":"这条路通向村子。"},{"en":"Look before you cross the road.","zh":"过马路前要看看。"}]', NULL, '🛣️', 2, '["core","place"]', 1793836800000, 1793836800000);
INSERT OR REPLACE INTO words (id, text, phonetic, part_of_speech, meaning_en, meaning_zh, definition_en, definition_zh, examples, image, emoji, level, tags, created_at, updated_at) VALUES ('w-explore-2-04', 'travel', '/ˈtrævl/', 'verb', 'to go from one place to another', '旅行', 'When you travel, you go to another place.', '旅行就是去另一个地方。', '[{"en":"We travel by train.","zh":"我们坐火车旅行。"},{"en":"I want to travel around the world.","zh":"我想环游世界。"}]', NULL, '🧳', 2, '["core","action"]', 1793836800000, 1793836800000);
INSERT OR REPLACE INTO words (id, text, phonetic, part_of_speech, meaning_en, meaning_zh, definition_en, definition_zh, examples, image, emoji, level, tags, created_at, updated_at) VALUES ('w-explore-2-05', 'climb', '/klaɪm/', 'verb', 'to go up something', '爬；攀登', 'When you climb, you go up a hill or a tree.', '爬，就是往山上或树上走。', '[{"en":"We climb the hill.","zh":"我们爬上山。"},{"en":"Can you climb that tree?","zh":"你能爬上那棵树吗？"}]', NULL, '🧗', 2, '["core","action"]', 1793836800000, 1793836800000);
INSERT OR REPLACE INTO words (id, text, phonetic, part_of_speech, meaning_en, meaning_zh, definition_en, definition_zh, examples, image, emoji, level, tags, created_at, updated_at) VALUES ('w-explore-2-06', 'around', '/əˈraʊnd/', 'preposition', 'on every side of something', '围绕；在……周围', 'When you go around something, you go from one side to the other.', '绕着某个东西走，就是从一边走到另一边。', '[{"en":"We walk around the lake.","zh":"我们绕着湖走。"},{"en":"Look around you.","zh":"看看你的四周。"}]', NULL, '🔄', 2, '["core","direction"]', 1793836800000, 1793836800000);
INSERT OR REPLACE INTO words (id, text, phonetic, part_of_speech, meaning_en, meaning_zh, definition_en, definition_zh, examples, image, emoji, level, tags, created_at, updated_at) VALUES ('w-explore-2-07', 'near', '/nɪə/', 'preposition', 'not far away', '靠近；在……附近', 'If something is near, it is close to you.', '如果某个东西很近，它就在你旁边。', '[{"en":"The river is near our house.","zh":"河离我们家很近。"},{"en":"Sit near the fire.","zh":"坐在火堆旁边。"}]', NULL, '📍', 2, '["core","direction"]', 1793836800000, 1793836800000);
INSERT OR REPLACE INTO words (id, text, phonetic, part_of_speech, meaning_en, meaning_zh, definition_en, definition_zh, examples, image, emoji, level, tags, created_at, updated_at) VALUES ('w-explore-2-08', 'up', '/ʌp/', 'adverb', 'to a higher place', '向上', 'When you go up, you go to a higher place.', '向上走，就是去更高的地方。', '[{"en":"We walk up the hill.","zh":"我们往山上走。"},{"en":"Look up at the sky.","zh":"抬头看天空。"}]', NULL, '⬆️', 2, '["core","direction"]', 1793836800000, 1793836800000);
INSERT OR REPLACE INTO words (id, text, phonetic, part_of_speech, meaning_en, meaning_zh, definition_en, definition_zh, examples, image, emoji, level, tags, created_at, updated_at) VALUES ('w-explore-2-09', 'down', '/daʊn/', 'adverb', 'to a lower place', '向下', 'When you go down, you go to a lower place.', '向下走，就是去更低的地方。', '[{"en":"We go down the path.","zh":"我们沿着小路往下走。"},{"en":"The sun goes down in the evening.","zh":"傍晚太阳落山。"}]', NULL, '⬇️', 2, '["core","direction"]', 1793836800000, 1793836800000);
INSERT OR REPLACE INTO words (id, text, phonetic, part_of_speech, meaning_en, meaning_zh, definition_en, definition_zh, examples, image, emoji, level, tags, created_at, updated_at) VALUES ('w-explore-2-10', 'path', '/pɑːθ/', 'noun', 'a narrow way for walking', '小路', 'A path is a small way where people walk.', '小路是人们走路的小道。', '[{"en":"The path goes through the forest.","zh":"小路穿过森林。"},{"en":"Follow the path to the lake.","zh":"沿着小路走到湖边。"}]', NULL, '🥾', 3, '["thematic","place"]', 1793836800000, 1793836800000);
INSERT OR REPLACE INTO words (id, text, phonetic, part_of_speech, meaning_en, meaning_zh, definition_en, definition_zh, examples, image, emoji, level, tags, created_at, updated_at) VALUES ('w-explore-2-11', 'bridge', '/brɪdʒ/', 'noun', 'something built over water or a road so people can cross', '桥', 'A bridge goes over water or a road.', '桥架在水面或道路上方。', '[{"en":"We walk across the bridge.","zh":"我们走过桥。"},{"en":"The bridge is made of stone.","zh":"这座桥是石头做的。"}]', NULL, '🌉', 3, '["core","place"]', 1793836800000, 1793836800000);
INSERT OR REPLACE INTO words (id, text, phonetic, part_of_speech, meaning_en, meaning_zh, definition_en, definition_zh, examples, image, emoji, level, tags, created_at, updated_at) VALUES ('w-explore-2-12', 'gate', '/ɡeɪt/', 'noun', 'a door in a wall or fence', '大门', 'A gate is a door in a wall or fence.', '大门是墙或栅栏上的一扇门。', '[{"en":"The gate is open.","zh":"大门开着。"},{"en":"Please close the gate.","zh":"请把大门关上。"}]', NULL, '🚪', 3, '["core","object"]', 1793836800000, 1793836800000);
INSERT OR REPLACE INTO words (id, text, phonetic, part_of_speech, meaning_en, meaning_zh, definition_en, definition_zh, examples, image, emoji, level, tags, created_at, updated_at) VALUES ('w-explore-2-13', 'torch', '/tɔːtʃ/', 'noun', 'a small light you can carry', '手电筒', 'A torch gives light when it is dark.', '天黑的时候，手电筒能照亮。', '[{"en":"Take a torch into the cave.","zh":"带一把手电筒进山洞。"},{"en":"My torch is bright.","zh":"我的手电筒很亮。"}]', NULL, '🔦', 3, '["thematic","tool"]', 1793836800000, 1793836800000);
INSERT OR REPLACE INTO words (id, text, phonetic, part_of_speech, meaning_en, meaning_zh, definition_en, definition_zh, examples, image, emoji, level, tags, created_at, updated_at) VALUES ('w-explore-2-14', 'corner', '/ˈkɔːnə/', 'noun', 'the place where two sides meet', '角落；拐角', 'A corner is where two walls or sides meet.', '角落是两面墙或两条边相交的地方。', '[{"en":"The shop is on the corner.","zh":"商店在街角。"},{"en":"Put the box in the corner.","zh":"把箱子放在角落里。"}]', NULL, '📐', 3, '["core","place"]', 1793836800000, 1793836800000);
INSERT OR REPLACE INTO words (id, text, phonetic, part_of_speech, meaning_en, meaning_zh, definition_en, definition_zh, examples, image, emoji, level, tags, created_at, updated_at) VALUES ('w-explore-2-15', 'across', '/əˈkrɒs/', 'preposition', 'from one side to the other', '穿过；横过', 'When you go across, you go from one side to the other.', '穿过，就是从一边走到另一边。', '[{"en":"We walk across the field.","zh":"我们走过田野。"},{"en":"She swims across the lake.","zh":"她游过湖面。"}]', NULL, '➡️', 3, '["core","direction"]', 1793836800000, 1793836800000);
INSERT OR REPLACE INTO words (id, text, phonetic, part_of_speech, meaning_en, meaning_zh, definition_en, definition_zh, examples, image, emoji, level, tags, created_at, updated_at) VALUES ('w-explore-2-16', 'follow', '/ˈfɒləʊ/', 'verb', 'to go after someone', '跟随', 'When you follow someone, you go behind them.', '跟随别人，就是跟在他后面走。', '[{"en":"Follow me to the river.","zh":"跟我到河边。"},{"en":"We follow the path.","zh":"我们沿着小路走。"}]', NULL, '👣', 3, '["core","action"]', 1793836800000, 1793836800000);
INSERT OR REPLACE INTO words (id, text, phonetic, part_of_speech, meaning_en, meaning_zh, definition_en, definition_zh, examples, image, emoji, level, tags, created_at, updated_at) VALUES ('w-explore-2-17', 'turn', '/tɜːn/', 'verb', 'to move in a different direction', '转弯；转向', 'When you turn, you move to another way.', '转弯，就是换一个方向走。', '[{"en":"Turn left at the gate.","zh":"在大门那里向左转。"},{"en":"The road turns near the river.","zh":"路在河边拐弯。"}]', NULL, '↩️', 3, '["core","action"]', 1793836800000, 1793836800000);
INSERT OR REPLACE INTO words (id, text, phonetic, part_of_speech, meaning_en, meaning_zh, definition_en, definition_zh, examples, image, emoji, level, tags, created_at, updated_at) VALUES ('w-explore-2-18', 'journey', '/ˈdʒɜːni/', 'noun', 'a long trip from one place to another', '旅程', 'A journey is a trip to another place.', '旅程就是去另一个地方的一段路。', '[{"en":"The journey takes two days.","zh":"这段旅程要两天。"},{"en":"We had a long journey home.","zh":"我们回家的路很长。"}]', NULL, '🛤️', 3, '["thematic","abstract"]', 1793836800000, 1793836800000);
INSERT OR REPLACE INTO words (id, text, phonetic, part_of_speech, meaning_en, meaning_zh, definition_en, definition_zh, examples, image, emoji, level, tags, created_at, updated_at) VALUES ('w-explore-2-19', 'adventure', '/ədˈventʃə/', 'noun', 'an exciting thing to do or see', '冒险', 'An adventure is exciting and new.', '冒险是让人兴奋的新鲜事。', '[{"en":"Our trip was a big adventure.","zh":"我们的旅行是一次大冒险。"},{"en":"She loves adventure.","zh":"她喜欢冒险。"}]', NULL, '🧭', 3, '["thematic","abstract"]', 1793836800000, 1793836800000);
INSERT OR REPLACE INTO words (id, text, phonetic, part_of_speech, meaning_en, meaning_zh, definition_en, definition_zh, examples, image, emoji, level, tags, created_at, updated_at) VALUES ('w-explore-2-20', 'explore', '/ɪkˈsplɔː/', 'verb', 'to look around a new place', '探索', 'When you explore, you look around a new place.', '探索就是在一个新地方到处看看。', '[{"en":"We explore the forest.","zh":"我们探索森林。"},{"en":"Let''s explore the cave.","zh":"我们去山洞里看看吧。"}]', NULL, '🔍', 3, '["thematic","action"]', 1793836800000, 1793836800000);
INSERT OR REPLACE INTO words (id, text, phonetic, part_of_speech, meaning_en, meaning_zh, definition_en, definition_zh, examples, image, emoji, level, tags, created_at, updated_at) VALUES ('w-explore-3-01', 'story', '/ˈstɔːri/', 'noun', 'words that tell about people and things that happen', '故事', 'A story tells what happens to someone.', '故事讲的是某个人遇到了什么事。', '[{"en":"Dad reads me a story.","zh":"爸爸给我读故事。"},{"en":"This story is about a bird.","zh":"这个故事讲的是一只鸟。"}]', NULL, '📖', 1, '["core","object"]', 1793836800000, 1793836800000);
INSERT OR REPLACE INTO words (id, text, phonetic, part_of_speech, meaning_en, meaning_zh, definition_en, definition_zh, examples, image, emoji, level, tags, created_at, updated_at) VALUES ('w-explore-3-02', 'robot', '/ˈrəʊbɒt/', 'noun', 'a machine that can move and do jobs', '机器人', 'A robot is a machine that can do things by itself.', '机器人是一种能自己干活的机器。', '[{"en":"The robot can walk.","zh":"这个机器人会走路。"},{"en":"I draw a robot.","zh":"我画了一个机器人。"}]', NULL, '🤖', 1, '["core","object"]', 1793836800000, 1793836800000);
INSERT OR REPLACE INTO words (id, text, phonetic, part_of_speech, meaning_en, meaning_zh, definition_en, definition_zh, examples, image, emoji, level, tags, created_at, updated_at) VALUES ('w-explore-3-03', 'machine', '/məˈʃiːn/', 'noun', 'a thing with parts that works to do a job', '机器', 'A machine has parts that move and work together.', '机器有很多零件一起转动、一起干活。', '[{"en":"This machine washes clothes.","zh":"这台机器能洗衣服。"},{"en":"The machine is very big.","zh":"这台机器很大。"}]', NULL, '⚙️', 2, '["core","object"]', 1793836800000, 1793836800000);
INSERT OR REPLACE INTO words (id, text, phonetic, part_of_speech, meaning_en, meaning_zh, definition_en, definition_zh, examples, image, emoji, level, tags, created_at, updated_at) VALUES ('w-explore-3-04', 'treasure', '/ˈtreʒə/', 'noun', 'gold, jewels, or other special things you find', '宝藏', 'Treasure is something special that people look for.', '宝藏是人们寻找的特别的东西。', '[{"en":"We found treasure in the cave.","zh":"我们在山洞里找到了宝藏。"},{"en":"The box is full of treasure.","zh":"盒子里装满了宝物。"}]', NULL, '💎', 2, '["thematic","object"]', 1793836800000, 1793836800000);
INSERT OR REPLACE INTO words (id, text, phonetic, part_of_speech, meaning_en, meaning_zh, definition_en, definition_zh, examples, image, emoji, level, tags, created_at, updated_at) VALUES ('w-explore-3-05', 'planet', '/ˈplænɪt/', 'noun', 'a big round world in space', '行星', 'A planet is a big round world that goes around a star.', '行星是一颗绕着恒星转的大圆球。', '[{"en":"Earth is our planet.","zh":"地球是我们的行星。"},{"en":"Mars is a red planet.","zh":"火星是一颗红色的行星。"}]', NULL, '🪐', 3, '["thematic","nature"]', 1793836800000, 1793836800000);
INSERT OR REPLACE INTO words (id, text, phonetic, part_of_speech, meaning_en, meaning_zh, definition_en, definition_zh, examples, image, emoji, level, tags, created_at, updated_at) VALUES ('w-explore-3-06', 'dinosaur', '/ˈdaɪnəsɔː/', 'noun', 'a very big animal that lived long ago', '恐龙', 'Dinosaurs were big animals that lived long ago.', '恐龙是很久以前生活的大动物。', '[{"en":"The dinosaur is very big.","zh":"这只恐龙很大。"},{"en":"I like dinosaur books.","zh":"我喜欢恐龙书。"}]', NULL, '🦕', 3, '["thematic","animal"]', 1793836800000, 1793836800000);
INSERT OR REPLACE INTO words (id, text, phonetic, part_of_speech, meaning_en, meaning_zh, definition_en, definition_zh, examples, image, emoji, level, tags, created_at, updated_at) VALUES ('w-explore-3-07', 'learn', '/lɜːn/', 'verb', 'to find out something new', '学习；学会', 'When you learn, you find out something new.', '学习就是发现新的事情。', '[{"en":"We learn about animals.","zh":"我们学习关于动物的知识。"},{"en":"I learn a new word every day.","zh":"我每天学一个新单词。"}]', NULL, '🧠', 1, '["core","action"]', 1793836800000, 1793836800000);
INSERT OR REPLACE INTO words (id, text, phonetic, part_of_speech, meaning_en, meaning_zh, definition_en, definition_zh, examples, image, emoji, level, tags, created_at, updated_at) VALUES ('w-explore-3-08', 'find', '/faɪnd/', 'verb', 'to see something you were looking for', '找到', 'When you find something, you see it after looking for it.', '找到，就是找了一会儿之后看见了它。', '[{"en":"I find a shell on the beach.","zh":"我在海滩上找到一个贝壳。"},{"en":"Can you find the map?","zh":"你能找到地图吗？"}]', NULL, '🔎', 1, '["core","action"]', 1793836800000, 1793836800000);
INSERT OR REPLACE INTO words (id, text, phonetic, part_of_speech, meaning_en, meaning_zh, definition_en, definition_zh, examples, image, emoji, level, tags, created_at, updated_at) VALUES ('w-explore-3-09', 'look', '/lʊk/', 'verb', 'to use your eyes', '看', 'When you look, you use your eyes to see.', '看，就是用眼睛去瞧。', '[{"en":"Look at the stars.","zh":"看那些星星。"},{"en":"I look out of the window.","zh":"我看向窗外。"}]', NULL, '👀', 1, '["core","action"]', 1793836800000, 1793836800000);
INSERT OR REPLACE INTO words (id, text, phonetic, part_of_speech, meaning_en, meaning_zh, definition_en, definition_zh, examples, image, emoji, level, tags, created_at, updated_at) VALUES ('w-explore-3-10', 'listen', '/ˈlɪsn/', 'verb', 'to hear something carefully', '听', 'When you listen, you try to hear a sound.', '听，就是用心去听一个声音。', '[{"en":"Listen to the birds.","zh":"听鸟儿叫。"},{"en":"I listen to a story.","zh":"我听故事。"}]', NULL, '👂', 1, '["core","action"]', 1793836800000, 1793836800000);
INSERT OR REPLACE INTO words (id, text, phonetic, part_of_speech, meaning_en, meaning_zh, definition_en, definition_zh, examples, image, emoji, level, tags, created_at, updated_at) VALUES ('w-explore-3-11', 'ask', '/ɑːsk/', 'verb', 'to say a question', '问', 'When you ask, you say a question.', '问，就是说一个问题。', '[{"en":"I ask my teacher a question.","zh":"我问老师一个问题。"},{"en":"Ask him where the path is.","zh":"问问他小路在哪里。"}]', NULL, '❓', 1, '["core","action"]', 1793836800000, 1793836800000);
INSERT OR REPLACE INTO words (id, text, phonetic, part_of_speech, meaning_en, meaning_zh, definition_en, definition_zh, examples, image, emoji, level, tags, created_at, updated_at) VALUES ('w-explore-3-12', 'show', '/ʃəʊ/', 'verb', 'to let someone see something', '给……看；展示', 'When you show something, you let someone see it.', '展示，就是让别人看到它。', '[{"en":"Show me your map.","zh":"给我看看你的地图。"},{"en":"I show my drawing to Mum.","zh":"我把画给妈妈看。"}]', NULL, '👋', 1, '["core","action"]', 1793836800000, 1793836800000);
INSERT OR REPLACE INTO words (id, text, phonetic, part_of_speech, meaning_en, meaning_zh, definition_en, definition_zh, examples, image, emoji, level, tags, created_at, updated_at) VALUES ('w-explore-3-13', 'try', '/traɪ/', 'verb', 'to do your best to do something', '尝试；努力', 'When you try, you do your best.', '尝试，就是尽你最大的努力去做。', '[{"en":"I try to climb the tree.","zh":"我试着爬上那棵树。"},{"en":"Try again.","zh":"再试一次。"}]', NULL, '💪', 1, '["core","action"]', 1793836800000, 1793836800000);
INSERT OR REPLACE INTO words (id, text, phonetic, part_of_speech, meaning_en, meaning_zh, definition_en, definition_zh, examples, image, emoji, level, tags, created_at, updated_at) VALUES ('w-explore-3-14', 'think', '/θɪŋk/', 'verb', 'to use your mind to make ideas', '想；思考', 'When you think, you use your mind.', '思考，就是用你的头脑。', '[{"en":"I think about the sea.","zh":"我想着大海。"},{"en":"Think before you answer.","zh":"回答前先想一想。"}]', NULL, '💭', 2, '["core","action"]', 1793836800000, 1793836800000);
INSERT OR REPLACE INTO words (id, text, phonetic, part_of_speech, meaning_en, meaning_zh, definition_en, definition_zh, examples, image, emoji, level, tags, created_at, updated_at) VALUES ('w-explore-3-15', 'remember', '/rɪˈmembə/', 'verb', 'to keep something in your mind', '记得', 'When you remember, you can think of something later.', '记得，就是过后还能想起一件事。', '[{"en":"I remember our trip.","zh":"我记得我们的旅行。"},{"en":"Remember to take a torch.","zh":"记得带手电筒。"}]', NULL, '📝', 3, '["core","action"]', 1793836800000, 1793836800000);
INSERT OR REPLACE INTO words (id, text, phonetic, part_of_speech, meaning_en, meaning_zh, definition_en, definition_zh, examples, image, emoji, level, tags, created_at, updated_at) VALUES ('w-explore-3-16', 'question', '/ˈkwestʃən/', 'noun', 'words you say when you want to know something', '问题', 'A question asks for an answer.', '问题是在向别人要一个答案。', '[{"en":"I have a question.","zh":"我有一个问题。"},{"en":"That is a good question.","zh":"那是个好问题。"}]', NULL, '❔', 1, '["core","abstract"]', 1793836800000, 1793836800000);
INSERT OR REPLACE INTO words (id, text, phonetic, part_of_speech, meaning_en, meaning_zh, definition_en, definition_zh, examples, image, emoji, level, tags, created_at, updated_at) VALUES ('w-explore-3-17', 'answer', '/ˈɑːnsə/', 'noun', 'words you say back to a question', '答案', 'An answer is what you say to a question.', '答案就是你对一个问题说的话。', '[{"en":"I know the answer.","zh":"我知道答案。"},{"en":"Your answer is right.","zh":"你的答案是对的。"}]', NULL, '✅', 1, '["core","abstract"]', 1793836800000, 1793836800000);
INSERT OR REPLACE INTO words (id, text, phonetic, part_of_speech, meaning_en, meaning_zh, definition_en, definition_zh, examples, image, emoji, level, tags, created_at, updated_at) VALUES ('w-explore-3-18', 'science', '/ˈsaɪəns/', 'noun', 'learning about the world by looking and testing', '科学', 'Science helps us learn how things work.', '科学帮助我们了解事物是怎么运作的。', '[{"en":"We learn science at school.","zh":"我们在学校学科学。"},{"en":"Science can explain the rain.","zh":"科学可以解释下雨。"}]', NULL, '🔬', 3, '["thematic","abstract"]', 1793836800000, 1793836800000);
INSERT OR REPLACE INTO words (id, text, phonetic, part_of_speech, meaning_en, meaning_zh, definition_en, definition_zh, examples, image, emoji, level, tags, created_at, updated_at) VALUES ('w-explore-3-19', 'idea', '/aɪˈdɪə/', 'noun', 'a thought or plan in your mind', '主意；想法', 'An idea is a thought that comes to your mind.', '主意是出现在你脑海里的想法。', '[{"en":"I have an idea.","zh":"我有一个主意。"},{"en":"That is a clever idea.","zh":"那是个聪明的主意。"}]', NULL, '💡', 2, '["core","abstract"]', 1793836800000, 1793836800000);
INSERT OR REPLACE INTO words (id, text, phonetic, part_of_speech, meaning_en, meaning_zh, definition_en, definition_zh, examples, image, emoji, level, tags, created_at, updated_at) VALUES ('w-explore-3-20', 'dream', '/driːm/', 'noun', 'pictures in your mind when you sleep', '梦', 'A dream is a story in your mind when you sleep.', '梦是你睡着时脑海里出现的故事。', '[{"en":"I had a dream about a dragon.","zh":"我梦见了一条龙。"},{"en":"My dream was about the sea.","zh":"我的梦是关于大海的。"}]', NULL, '🌙', 2, '["core","abstract","emotional"]', 1793836800000, 1793836800000);

